# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HZ. EBU BEKİR\'İN KİŞİLİK ÖZELLİKLERİ VE SOSYAL HAYATA ETKİSİ (PH.10.2.1)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">AHLAKİ VE İNSANİ ERDEMLERİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Sıdk ve Sadakat: Tereddütsüz tasdik («es-Sıddîk»)</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• Hilm ve Merhamet: Yumuşak huylu, gözü yaşlı («Evvâh»)</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• Cömertlik ve İnfak: Malını mazlumlar ve İslam için harcama</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• Tevazu ve Vefa: Halife iken bile yetim ve yaşlılara hizmet</text>\n  <text x="35" y="184" font-size="11.2" fill="#1e3a8a">• İlim ve Feraset: Arap ensâb (soy) ve tarih ilminde uzmanlık</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TOPLUMSAL VE YÖNETİMSEL YANSIMALARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Güvenilir tüccar kimliğiyle pek çok sahâbînin hidayetine vesile</text>\n  <text x="370" y="112" font-size="11.2" fill="#14532d">• İlk Hilafet Hutbesi: Adalet, şeffaflık ve hakkaniyet ilkesi</text>\n  <text x="370" y="136" font-size="11.2" fill="#14532d">• «İçinizdeki en zayıf, hakkını alıncaya kadar yanımda en güçlüdür»</text>\n  <text x="370" y="160" font-size="11.2" fill="#14532d">• İstişare (Şûrâ) geleneği ve Üsâme ordusunun gönderilmesi</text>\n  <text x="370" y="184" font-size="11.2" fill="#14532d">• Kur\'an-ı Kerim\'in iki kapak arasında toplanması (Cem\'u\'l-Kur\'ân)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Ebu Bekir (r.a.), şefkat ile kararlılığı şahsiyetinde birleştirerek İslam toplumunun birliğini korumuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HZ. EBU BEKİR\'İN KIZLARI: HZ. AİŞE VE HZ. ESMA (PH.10.2.2)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">MÜMİNLERİN ANNESİ HZ. AİŞE (R.A.)</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Peygamberimizin eşi ve İslam tarihinin en büyük kadın âlimi</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• 2210 hadis rivayetiyle «Müksirûn» (en çok hadis nakleden) sahâbî</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">• Tefsir, hadis, fıkıh, Arap edebiyatı ve tıpta başvuru mercii</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• Suffe ve Medine Mektebi\'nde yüzlerce talebe yetiştirdi</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• İfk Hadisesi\'nde Nûr suresi 11-20. ayetlerle masumiyeti bildirildi</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">ZÂTÜ\'N-NİTÂKAYN HZ. ESMA (R.A.)</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Hz. Aişe\'nin ablası, Zübeyr b. Avvâm\'ın eşi, Abdullah\'ın annesi</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">• Mekke\'de İslam\'ı ilk kabul eden öncü sahâbîlerden (Sâbikûn)</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">• Hicret gecesi Sevr Mağarası\'na gizlice azık ve su taşıdı</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Kuşağını ikiye bölüp azık bağladığı için «Zâtü\'n-Nitâkayn»</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">• Ebû Cehil\'in baskısına boyun eğmeyen cesaretiyle tanındı</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Aişe ilmi ve fıkhıyla, Hz. Esma ise Hicret\'teki fedakârlığı ve cesaretiyle İslam tarihine damga vurmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HZ. EBU BEKİR\'İN OĞULLARI VE DÖRT KUŞAK SAHÂBÎ AİLESİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">ABDULLAH B. EBÎ BEKİR (R.A.)</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• İlk Müslümanlardan; zeki, ketum ve cesur bir genç sahâbî</text>\n  <text x="35" y="112" font-size="11.2" fill="#713f12">• Hicret\'te 3 gün boyunca Mekke\'deki müşrik planlarını dinledi</text>\n  <text x="35" y="136" font-size="11.2" fill="#713f12">• Gece karanlığında Sevr Mağarası\'na çıkıp istihbarat ulaştırdı</text>\n  <text x="35" y="160" font-size="11.2" fill="#713f12">• Seher vakti Mekke\'de gecelemiş gibi şehre geri döndü</text>\n  <text x="35" y="184" font-size="11.2" fill="#713f12">• Tâif Kuşatması\'nda aldığı ok yarası sonucu 633\'te şehit oldu</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">ABDURRAHMAN, MUHAMMED VE ÜMMÜ KÜLSÛM</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• Abdurrahman b. Ebî Bekir: Hz. Ebu Bekir\'in en büyük oğlu</text>\n  <text x="370" y="112" font-size="11.2" fill="#064e3b">  Hudeybiye Antlaşması sürecinde Müslüman oldu; Yemâme kahramanı</text>\n  <text x="370" y="136" font-size="11.2" fill="#064e3b">• Muhammed b. Ebî Bekir: Veda Haccı yolunda (Zülhuleyfe) doğdu</text>\n  <text x="370" y="160" font-size="11.2" fill="#064e3b">• Ümmü Külsûm bint Ebî Bekir: Babasının vefatından sonra doğdu</text>\n  <text x="370" y="184" font-size="11.2" fill="#064e3b">• Babası Ebû Kuhâfe → Ebu Bekir → Esma → Abdullah: 4 kuşak sahâbî!</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İslam tarihinde dört kuşağı birden sahâbî olma şerefine erişen tek aile Hz. Ebu Bekir\'in ailesidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
